<?php require_once __DIR__ . '/../includes/functions.php'; require_once __DIR__ . '/../includes/database.php'; start_secure_session(); if(!empty($_SESSION['admin_id'])){header('Location: dashboard.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf_token']??null))$error='Your session expired. Please try again.';else{$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');try{$stmt=db()->prepare('SELECT id,password_hash FROM admins WHERE email=? LIMIT 1');$stmt->execute([$email?:'']);$admin=$stmt->fetch();if($admin&&password_verify($password,$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];header('Location: dashboard.php');exit;}$error='Invalid email or password.';}catch(Throwable $e){$error='Admin setup is unavailable. Set VEYTRONATECH_ADMIN_PASSWORD and ensure SQLite is available.';}}} ?>
